        let mismatches = Mismatches("dividingWhere with mask \(describe(mask))")
        let aInputs = Inputs.vectors(H.self, seed: 0x0969_16BB_C715_7F72)
        let bInputs =
            Inputs.vectors(H.self, seed: 0x0969_15BB_C715_7DBF) + [H(H.SIMDType(repeating: -1))]
            + Inputs.vectors(H.self, seed: 0x413B_A5F1_AABF_8650).enumerated().map {
                index,
                vector in H(vector.simd &>> H.SIMDType(repeating: Lane(truncatingIfNeeded: index)))
            }
        for (a, b) in everyPair(aInputs, bInputs) {
            mismatches.check(
                H.dividing(a, b, where: mask),
                H(raw: HighwayReference.dividingWhereI64(mask.raw, a.raw, b.raw)),
                "a: \(describe(a)), b: \(describe(b))"
            )
        }
        mismatches.record()
    }

